import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif

/// Namespace of the request types generated from the PVE API schema (`Generated/`).
public enum PVEAPI {}

/// One API call: HTTP method, escaped path and its (non-path) parameters. Conformances are
/// generated by `scripts/generate-pvekit-api.py`; see `PVEAPI`.
public protocol PVEAPIRequest: Sendable {
    associatedtype Response: Decodable & Sendable

    static var method: HTTPMethod { get }
    /// Path as written in the schema, e.g. `/nodes/{node}/qemu/{vmid}/status/current`.
    static var pathTemplate: String { get }
    /// The schema's internal method name (e.g. `vm_status`).
    static var schemaName: String { get }

    /// Escaped path with the path parameters filled in.
    var path: String { get }
    /// Query (GET / DELETE) or form (POST / PUT) parameters, in a stable order.
    var parameters: [(String, String)] { get }
}

/// Values that can be sent as an API parameter.
public protocol PVEParameterValue {
    var parameterValue: String { get }
}

extension String: PVEParameterValue {
    public var parameterValue: String { self }
}

extension Int: PVEParameterValue {
    public var parameterValue: String { String(self) }
}

extension Double: PVEParameterValue {
    public var parameterValue: String {
        rounded() == self && abs(self) < 1e15 ? String(Int64(self)) : String(self)
    }
}

extension Bool: PVEParameterValue {
    /// PVE booleans are `0` / `1`.
    public var parameterValue: String { self ? "1" : "0" }
}

extension RawRepresentable where RawValue == String {
    public var parameterValue: String { rawValue }
}

extension Array where Element == (String, String) {
    /// Appends `prefix0=…`, `prefix1=…` in index order (`net[n]`-style parameters).
    mutating func appendIndexed(_ prefix: String, _ values: [Int: String]) {
        for index in values.keys.sorted() {
            append(("\(prefix)\(index)", values[index]!))
        }
    }
}

extension KeyedDecodingContainer where Key == AnyCodingKey {
    /// Array of scalars where single elements may arrive in another representation.
    func lenientArray<T: Decodable>(_ type: T.Type, forKey key: AnyCodingKey) -> [T]? {
        if let values = try? decodeIfPresent([T].self, forKey: key) { return values }
        guard let raw = try? decodeIfPresent([JSONValue].self, forKey: key) else { return nil }
        return raw.compactMap { value -> T? in
            switch T.self {
            case is String.Type: return (value.stringValue ?? (value.doubleValue.map { $0.parameterValue })) as? T
            case is Int.Type: return value.doubleValue.map { Int($0) } as? T
            case is Double.Type: return value.doubleValue as? T
            case is Bool.Type: return value.doubleValue.map { $0 != 0 } as? T
            default: return nil
            }
        }
    }

    /// Collects `prefix0`, `prefix1`, … into a dictionary keyed by the index.
    func indexedStrings(prefix: String) -> [Int: String] {
        var result: [Int: String] = [:]
        for key in allKeys where key.stringValue.hasPrefix(prefix) {
            let suffix = key.stringValue.dropFirst(prefix.count)
            guard !suffix.isEmpty, suffix.allSatisfy(\.isNumber), let index = Int(suffix) else { continue }
            if let value = flexibleString(key) { result[index] = value }
        }
        return result
    }
}

extension PVEClient {
    /// Sends a generated request and decodes its schema response type.
    public func send<R: PVEAPIRequest>(_ request: R) async throws -> R.Response {
        try await send(request, as: R.Response.self)
    }

    /// Sends a generated request and decodes the `data` member as `T` (used where a hand-written
    /// model is more precise than the schema).
    public func send<R: PVEAPIRequest, T: Decodable & Sendable>(_ request: R, as type: T.Type) async throws -> T {
        if R.method.isWrite {
            return try await self.request(R.method, request.path, form: request.parameters, as: type)
        }
        let query = request.parameters.map { URLQueryItem(name: $0.0, value: $0.1) }
        return try await self.request(R.method, request.path, query: query, as: type)
    }
}
